		}
	}

	private boolean shouldAlertGimBroadcastType(BroadcastType type)
	{
		switch (type)
		{
			case RARE_DROP:
				return config.gimRareDrop();
			case RAID_LOOT:
				return config.gimRaidLoot();
			case REGULAR_DROP:
				return config.gimRegularDrop();
			case CLUE_LOOT:
